create function public.gateway_admin_command(p_actor uuid,p_payload jsonb) returns jsonb language plpgsql security definer set search_path='' as $$declare a text:=p_payload->>'action';i uuid:=(p_payload->>'id')::uuid;r jsonb;t app_private.targets;f app_private.favorites;v integer;n bigint;begin perform app_private.require_admin(p_actor);perform 1 from app_private.app_state where id=1 for update;r:=app_private.replay('admin',p_actor,p_payload);if r is not null then return r;end if;
case a
when 'create_team' then insert into app_private.teams(name,normalized_name) values(p_payload->>'name',p_payload->>'normalizedName') returning id into i;
when 'create_category' then insert into app_private.categories(name,normalized_name,kind) values(p_payload->>'name',p_payload->>'normalizedName',p_payload->>'kind') returning id into i;
when 'edit_team' then select version into v from app_private.teams where id=i for update;if v is null or v<>(p_payload->>'expectedVersion')::int then perform app_private.fail('VERSION_CONFLICT');end if;update app_private.teams set name=p_payload->>'name',normalized_name=p_payload->>'normalizedName',selectable=(p_payload->>'selectable')::boolean,version=version+1 where id=i;
when 'edit_category' then select version into v from app_private.categories where id=i for update;if v is null or v<>(p_payload->>'expectedVersion')::int then perform app_private.fail('VERSION_CONFLICT');end if;update app_private.categories set name=p_payload->>'name',normalized_name=p_payload->>'normalizedName',selectable=(p_payload->>'selectable')::boolean,version=version+1 where id=i;
when 'edit_participant_team' then select version into v from app_private.participants where id=i for update;if v is null or v<>(p_payload->>'expectedVersion')::int then perform app_private.fail('VERSION_CONFLICT');end if;if not exists(select 1 from app_private.teams where id=(p_payload->>'teamId')::uuid and selectable) then perform app_private.fail('VALIDATION_ERROR');end if;update app_private.participants set team_id=(p_payload->>'teamId')::uuid,version=version+1 where id=i;
when 'edit_course' then select * into t from app_private.targets where id=i for update;if not found then perform app_private.fail('TARGET_GONE');end if;if t.kind<>'COURSE' then perform app_private.fail('VALIDATION_ERROR');end if;if t.version<>(p_payload->>'expectedVersion')::int then perform app_private.fail('VERSION_CONFLICT');end if;perform app_private.validate_points(p_payload->'points');update app_private.targets set name=p_payload->>'name',route_json=jsonb_build_object('type','LineString','coordinates',p_payload->'points'),lng=(p_payload#>>'{points,0,0}')::float8,lat=(p_payload#>>'{points,0,1}')::float8,approximate_length_m=app_private.route_length(p_payload->'points'),version=version+1 where id=i;
when 'delete_favorite' then select * into f from app_private.favorites where id=i for update;if not found then perform app_private.fail('TARGET_GONE');end if;if f.version<>(p_payload->>'expectedVersion')::int then perform app_private.fail('VERSION_CONFLICT');end if;perform app_private.detach(i);delete from app_private.favorites where id=i;update app_private.targets set version=version+1 where id=f.target_id;
when 'delete_target' then select * into t from app_private.targets where id=i for update;if not found then perform app_private.fail('TARGET_GONE');end if;select count(*) into n from app_private.favorites where target_id=i;if t.version<>(p_payload->>'expectedVersion')::int or n<>(p_payload->>'expectedCount')::bigint then perform app_private.fail('VERSION_CONFLICT',jsonb_build_object('version',t.version,'count',n));end if;for f in select * from app_private.favorites where target_id=i order by id loop perform app_private.detach(f.id);end loop;delete from app_private.favorites where target_id=i;delete from app_private.targets where id=i;
else perform app_private.fail('VALIDATION_ERROR');end case;return app_private.record('admin',p_actor,p_payload,a,i);exception when unique_violation then perform app_private.fail('VALIDATION_ERROR');end$$;
create function public.gateway_admin_read(p_actor uuid,p_action text,p_id uuid default null,p_query text default '',p_cursor text default null) returns jsonb language plpgsql security definer set search_path='' as $$declare r jsonb;begin perform app_private.require_admin(p_actor);case p_action
when 'catalog' then return public.read_catalog();
when 'participants' then with page as(select p.*,t.name team_name from app_private.participants p join app_private.teams t on t.id=p.team_id where(p.nickname ilike '%'||p_query||'%' or p.id::text ilike '%'||p_query||'%') and(p_cursor is null or p.id>p_cursor::uuid) order by p.id limit 21),v as(select * from page order by id limit 20) select jsonb_build_object('participants',coalesce((select jsonb_agg(jsonb_build_object('id',id,'nickname',nickname,'teamId',team_id,'teamName',team_name,'version',version) order by id) from v),'[]'::jsonb),'nextCursor',case when(select count(*) from page)>20 then(select max(id::text) from v) else null end) into r;return r;
when 'targets' then with page as(select t.*,(select count(*) from app_private.favorites where target_id=t.id) cnt from app_private.targets t where(t.name ilike '%'||p_query||'%' or t.id::text ilike '%'||p_query||'%') and(p_cursor is null or t.id>p_cursor::uuid) order by t.id limit 21),v as(select * from page order by id limit 20) select jsonb_build_object('targets',coalesce((select jsonb_agg(jsonb_build_object('id',id,'name',name,'kind',kind,'count',cnt,'version',version,'points',route_json->'coordinates') order by id) from v),'[]'::jsonb),'nextCursor',case when(select count(*) from page)>20 then(select max(id::text) from v) else null end) into r;return r;
when 'deletion-preview' then select jsonb_build_object('targetId',t.id,'name',t.name,'version',t.version,'count',(select count(*) from app_private.favorites where target_id=t.id)) into r from app_private.targets t where t.id=p_id;if r is null then perform app_private.fail('TARGET_GONE');end if;return r;
when 'operations' then return jsonb_build_object('storage',(select jsonb_build_object('limitBytes',b.limit_bytes::text,'heldBytes',coalesce(sum(m.reserved_bytes),0)::text,'storedBytes',coalesce(sum(m.actual_bytes) filter(where m.state<>'deleted'),0)::text,'pendingCleanupBytes',coalesce(sum(m.reserved_bytes) filter(where m.state='delete_pending'),0)::text,'reconciledAt',b.reconciled_at,'hasUntrackedObjects',b.has_untracked_objects) from app_private.storage_budget b left join app_private.media_objects m on m.state<>'deleted' where b.id=1 group by b.id),'backups',jsonb_build_object('activeRun',(select to_jsonb(x)-'lease_token' from app_private.backup_runs x where status='running' limit 1),'lastSucceeded',(select to_jsonb(x)-'lease_token' from app_private.backup_runs x where status='succeeded' order by completed_at desc limit 1),'lastFailed',(select to_jsonb(x)-'lease_token' from app_private.backup_runs x where status='failed' order by completed_at desc limit 1)));
else perform app_private.fail('VALIDATION_ERROR');end case;end$$;
create function public.gateway_rate(p_scope text,p_key_hash text,p_limit integer,p_seconds integer) returns jsonb language plpgsql security definer set search_path='' as $$declare n integer;w bigint;begin if p_limit<1 or p_seconds<1 then perform app_private.fail('VALIDATION_ERROR');end if;w:=floor(extract(epoch from now())/p_seconds);insert into app_private.rate_counters values(p_scope,p_key_hash,w,1,now()+make_interval(secs=>p_seconds*2)) on conflict(scope,key_hash,window_start) do update set count=app_private.rate_counters.count+1 returning count into n;if n>p_limit then perform app_private.fail('RATE_LIMITED',jsonb_build_object('retryAfterSeconds',p_seconds));end if;return jsonb_build_object('allowed',true);end$$;

create function app_private.reserve_check(p_bytes bigint) returns void language plpgsql set search_path='' as $$begin if exists(select 1 from app_private.storage_budget where id=1 and(has_untracked_objects or limit_bytes<(select coalesce(sum(reserved_bytes),0) from app_private.media_objects where state<>'deleted')+p_bytes)) then perform app_private.fail('CAPACITY_REACHED');end if;end$$;
create function public.gateway_reserve_media(p_actor uuid,p_payload jsonb) returns jsonb language plpgsql security definer set search_path='' as $$declare id uuid:=gen_random_uuid();attempt uuid:=gen_random_uuid();r jsonb;k text;begin perform app_private.require_identity(p_actor);perform 1 from app_private.storage_budget where storage_budget.id=1 for update;perform 1 from app_private.browser_identities where browser_identities.id=p_actor for update;r:=app_private.replay('media',p_actor,p_payload);if r is not null then return r;end if;if(p_payload->>'byteSize')::bigint not between 1 and 524288 then perform app_private.fail('MEDIA_TOO_LARGE');end if;if(select count(*) from app_private.photo_assets where owner_identity_id=p_actor and state in('uploading','processing','ready'))>=6 then perform app_private.fail('CAPACITY_REACHED');end if;perform app_private.reserve_check(1114112);insert into app_private.photo_assets(id,owner_identity_id) values(id,p_actor);k:=id::text||'/'||attempt::text||'/raw.jpg';insert into app_private.media_objects(object_key,asset_id,variant,attempt_id,reserved_bytes,state,upload_expires_at) values(k,id,'raw',attempt,524288,'reserved',now()+interval '2 hours'),(id::text||'/'||attempt::text||'/full.jpg',id,'final',attempt,524288,'reserved',null),(id::text||'/'||attempt::text||'/thumb.jpg',id,'thumb',attempt,65536,'reserved',null);r:=jsonb_build_object('assetId',id,'rawObjectKey',k,'uploadExpiresAt',now()+interval '2 hours','state','uploading');insert into app_private.commands values('media',p_actor,(p_payload->>'requestKey')::uuid,p_payload->>'payloadHash','reserve_media',id,r,0,now());return r;end$$;
create function public.gateway_extend_upload(p_actor uuid,p_asset_id uuid,p_expires_at timestamptz) returns jsonb language plpgsql security definer set search_path='' as $$begin perform app_private.require_identity(p_actor);perform 1 from app_private.storage_budget where id=1 for update;perform 1 from app_private.photo_assets where id=p_asset_id and owner_identity_id=p_actor and state='uploading' for update;if not found then perform app_private.fail('PHOTO_GONE');end if;update app_private.media_objects set upload_expires_at=greatest(upload_expires_at,p_expires_at) where asset_id=p_asset_id and variant='raw' and state<>'deleted';return jsonb_build_object('ok',true);end$$;
create function public.gateway_claim_media(p_actor uuid,p_asset_id uuid) returns jsonb language plpgsql security definer set search_path='' as $$declare a app_private.photo_assets;attempt uuid;raw text;fullkey text;thumbkey text;token uuid:=gen_random_uuid();begin perform app_private.require_identity(p_actor);perform 1 from app_private.storage_budget where id=1 for update;select * into a from app_private.photo_assets where id=p_asset_id for update;if not found or a.owner_identity_id<>p_actor or a.state in('deleting','deleted') or a.expires_at<=now() then perform app_private.fail('PHOTO_GONE');end if;if a.state in('ready','attached') then return jsonb_build_object('state','ready');end if;if a.state='processing' and a.lease_until>now() then return jsonb_build_object('state','pending');end if;select object_key,attempt_id into raw,attempt from app_private.media_objects where asset_id=a.id and variant='raw' and state<>'deleted' order by created_at limit 1;
if a.state='processing' then perform app_private.reserve_check(589824);update app_private.media_objects set state='delete_pending' where asset_id=a.id and variant in('final','thumb') and state<>'deleted';insert into app_private.cleanup_jobs(object_key) select object_key from app_private.media_objects where asset_id=a.id and variant in('final','thumb') and state='delete_pending' on conflict(object_key) do nothing;attempt:=gen_random_uuid();insert into app_private.media_objects(object_key,asset_id,variant,attempt_id,reserved_bytes,state,writer_lease_until) values(a.id::text||'/'||attempt::text||'/full.jpg',a.id,'final',attempt,524288,'reserved',now()+interval '5 minutes'),(a.id::text||'/'||attempt::text||'/thumb.jpg',a.id,'thumb',attempt,65536,'reserved',now()+interval '5 minutes');end if;fullkey:=a.id::text||'/'||attempt::text||'/full.jpg';thumbkey:=a.id::text||'/'||attempt::text||'/thumb.jpg';update app_private.media_objects set writer_lease_until=now()+interval '5 minutes' where object_key in(fullkey,thumbkey);update app_private.photo_assets set state='processing',lease_token=token,lease_until=now()+interval '5 minutes',final_object_key=fullkey,thumb_object_key=thumbkey where id=a.id;return jsonb_build_object('state','processing','leaseToken',token,'rawObjectKey',raw,'finalObjectKey',fullkey,'thumbObjectKey',thumbkey,'writerLeaseUntil',now()+interval '5 minutes');end$$;
create function public.gateway_complete_media(p_actor uuid,p_payload jsonb) returns jsonb language plpgsql security definer set search_path='' as $$declare a app_private.photo_assets;begin perform app_private.require_identity(p_actor);perform 1 from app_private.storage_budget where id=1 for update;select * into a from app_private.photo_assets where id=(p_payload->>'assetId')::uuid for update;if not found or a.owner_identity_id<>p_actor then perform app_private.fail('PHOTO_GONE');end if;if a.state in('ready','attached') then return jsonb_build_object('state','ready');end if;if a.state<>'processing' or a.lease_token<>(p_payload->>'leaseToken')::uuid or a.lease_until<=now() then perform app_private.fail('VERSION_CONFLICT');end if;if(p_payload->>'fullBytes')::bigint not between 1 and 524288 or(p_payload->>'thumbBytes')::bigint not between 1 and 65536 then perform app_private.fail('MEDIA_TOO_LARGE');end if;update app_private.media_objects set actual_bytes=(p_payload->>'fullBytes')::bigint,reserved_bytes=(p_payload->>'fullBytes')::bigint,sha256=p_payload->>'fullSha256',state='stored',writer_lease_until=null where object_key=a.final_object_key;update app_private.media_objects set actual_bytes=(p_payload->>'thumbBytes')::bigint,reserved_bytes=(p_payload->>'thumbBytes')::bigint,sha256=p_payload->>'thumbSha256',state='stored',writer_lease_until=null where object_key=a.thumb_object_key;update app_private.media_objects set state='delete_pending' where asset_id=a.id and variant='raw' and state<>'deleted';insert into app_private.cleanup_jobs(object_key) select object_key from app_private.media_objects where asset_id=a.id and variant='raw' on conflict(object_key) do nothing;update app_private.photo_assets set state='ready',lease_token=null,lease_until=null where id=a.id;return jsonb_build_object('state','ready','assetId',a.id,'byteSize',p_payload->>'fullBytes');end$$;
create function public.gateway_fail_media(p_actor uuid,p_asset_id uuid,p_lease_token uuid) returns jsonb language plpgsql security definer set search_path='' as $$begin perform app_private.require_identity(p_actor);perform 1 from app_private.storage_budget where id=1 for update;perform 1 from app_private.photo_assets where id=p_asset_id and owner_identity_id=p_actor and lease_token=p_lease_token and state='processing' for update;if not found then return jsonb_build_object('state','gone');end if;update app_private.photo_assets set lease_until=now() where id=p_asset_id;return jsonb_build_object('state','failed');end$$;
create function public.gateway_photo(p_asset_id uuid,p_size text) returns jsonb language plpgsql security definer set search_path='' as $$declare k text;begin select case when p_size='thumb' then a.thumb_object_key when p_size='full' then a.final_object_key else null end into k from app_private.photo_assets a join app_private.favorites f on f.id=a.favorite_id where a.id=p_asset_id and a.state='attached';if k is null then perform app_private.fail('PHOTO_GONE');end if;return jsonb_build_object('objectKey',k);end$$;

create function app_private.expire_backups() returns void language sql set search_path='' as $$update app_private.backup_runs set status='failed',completed_at=now(),lease_token=null,lease_until=null,error_code='LEASE_EXPIRED' where status='running' and lease_until<=now()$$;
create function public.gateway_claim_cleanup(p_limit integer default 100) returns jsonb language plpgsql security definer set search_path='' as $$declare r jsonb;expired record;begin perform 1 from app_private.storage_budget where id=1 for update;perform app_private.expire_backups();if exists(select 1 from app_private.backup_runs where status='running') then return '[]';end if;for expired in select id from app_private.photo_assets where favorite_id is null and state not in('deleting','deleted') and expires_at<=now() and(lease_until is null or lease_until<=now()) order by id for update loop update app_private.photo_assets set state='deleting' where id=expired.id;update app_private.media_objects set state='delete_pending' where asset_id=expired.id and state<>'deleted';insert into app_private.cleanup_jobs(object_key) select object_key from app_private.media_objects where asset_id=expired.id and state='delete_pending' on conflict(object_key) do nothing;end loop;
with candidates as(select j.object_key from app_private.cleanup_jobs j join app_private.media_objects m on m.object_key=j.object_key join app_private.photo_assets asset on asset.id=m.asset_id where j.completed_at is null and j.next_attempt_at<=now() and(j.lease_until is null or j.lease_until<=now()) and(m.upload_expires_at is null or m.upload_expires_at<=now()) and(m.writer_lease_until is null or m.writer_lease_until<=now()) and not(asset.state='attached' and j.object_key in(asset.final_object_key,asset.thumb_object_key)) order by j.object_key limit least(100,greatest(1,p_limit)) for update of j skip locked),claimed as(update app_private.cleanup_jobs j set lease_token=gen_random_uuid(),lease_until=now()+interval '5 minutes' from candidates c where j.object_key=c.object_key returning j.object_key,j.lease_token) select coalesce(jsonb_agg(jsonb_build_object('objectKey',object_key,'leaseToken',lease_token)),'[]'::jsonb) into r from claimed;delete from app_private.rate_counters where expires_at<now();return r;end$$;
create function public.gateway_finish_cleanup(p_payload jsonb) returns jsonb language plpgsql security definer set search_path='' as $$declare j app_private.cleanup_jobs;m app_private.media_objects;a app_private.photo_assets;begin perform 1 from app_private.storage_budget where id=1 for update;select * into m from app_private.media_objects where object_key=p_payload->>'objectKey';select * into a from app_private.photo_assets where id=m.asset_id for update;select * into m from app_private.media_objects where object_key=p_payload->>'objectKey' for update;select * into j from app_private.cleanup_jobs where object_key=m.object_key for update;if j.completed_at is not null then return jsonb_build_object('ok',true);end if;if j.lease_token is distinct from(p_payload->>'leaseToken')::uuid or j.lease_until<=now() then perform app_private.fail('VERSION_CONFLICT');end if;if(p_payload->>'success')::boolean then if exists(select 1 from app_private.backup_runs where status='running' and lease_until>now()) or(a.state='attached' and m.object_key in(a.final_object_key,a.thumb_object_key)) or m.upload_expires_at>now() or m.writer_lease_until>now() then perform app_private.fail('VERSION_CONFLICT');end if;update app_private.media_objects set state='deleted',reserved_bytes=0,released_at=now() where object_key=m.object_key;update app_private.cleanup_jobs set completed_at=now(),lease_token=null,lease_until=null where object_key=m.object_key;if a.state='deleting' and not exists(select 1 from app_private.media_objects where asset_id=a.id and state<>'deleted') then update app_private.photo_assets set state='deleted' where id=a.id;end if;else update app_private.cleanup_jobs set attempts=attempts+1,next_attempt_at=now()+make_interval(secs=>least(3600,60*power(2,least(attempts,6))::int)),lease_token=null,lease_until=null where object_key=m.object_key;end if;return jsonb_build_object('ok',true);end$$;
create function public.gateway_reconcile_media(p_payload jsonb) returns jsonb language plpgsql security definer set search_path='' as $$declare o jsonb;m app_private.media_objects;unknown boolean:=false;begin perform 1 from app_private.storage_budget where id=1 for update;for o in select value from jsonb_array_elements(p_payload->'objects') order by value->>'objectKey' loop select * into m from app_private.media_objects where object_key=o->>'objectKey';if not found then unknown:=true;else perform 1 from app_private.photo_assets where id=m.asset_id for update;if m.state='deleted' then update app_private.media_objects set state='delete_pending',actual_bytes=(o->>'byteSize')::bigint,reserved_bytes=(o->>'byteSize')::bigint,released_at=null where object_key=m.object_key;insert into app_private.cleanup_jobs(object_key) values(m.object_key) on conflict(object_key) do update set completed_at=null,next_attempt_at=now();else update app_private.media_objects set actual_bytes=(o->>'byteSize')::bigint,reserved_bytes=greatest(reserved_bytes,(o->>'byteSize')::bigint) where object_key=m.object_key;end if;end if;end loop;update app_private.storage_budget set has_untracked_objects=has_untracked_objects or unknown,reconciled_at=case when(p_payload->>'complete')::boolean then now() else reconciled_at end where id=1;return jsonb_build_object('hasUntrackedObjects',unknown);end$$;
create function public.gateway_start_backup(p_actor uuid,p_payload jsonb) returns jsonb language plpgsql security definer set search_path='' as $$declare b app_private.backup_runs;begin perform app_private.require_admin(p_actor);perform 1 from app_private.storage_budget where id=1 for update;perform app_private.expire_backups();select * into b from app_private.backup_runs where actor_auth_user_id=p_actor and request_key=(p_payload->>'requestKey')::uuid;if found then return to_jsonb(b);end if;if exists(select 1 from app_private.backup_runs where status='running') then perform app_private.fail('BACKUP_IN_PROGRESS');end if;if exists(select 1 from app_private.cleanup_jobs where completed_at is null and lease_until>now()) then perform app_private.fail('BACKUP_IN_PROGRESS');end if;insert into app_private.backup_runs(actor_auth_user_id,request_key,lease_token,lease_until) values(p_actor,(p_payload->>'requestKey')::uuid,gen_random_uuid(),now()+interval '10 minutes') returning * into b;return to_jsonb(b);end$$;
create function public.gateway_update_backup(p_actor uuid,p_id uuid,p_payload jsonb) returns jsonb language plpgsql security definer set search_path='' as $$declare b app_private.backup_runs;a text:=p_payload->>'action';begin perform app_private.require_admin(p_actor);perform 1 from app_private.storage_budget where id=1 for update;select * into b from app_private.backup_runs where id=p_id for update;if not found or b.actor_auth_user_id<>p_actor then perform app_private.fail('FORBIDDEN');end if;if b.status='succeeded' and a='complete' and b.manifest_sha256=p_payload->>'manifestSha256' and b.archive_sha256=p_payload->>'archiveSha256' then return to_jsonb(b);end if;if b.status<>'running' or b.lease_token is distinct from(p_payload->>'leaseToken')::uuid or b.lease_until<=now() then perform app_private.fail('BACKUP_LEASE_EXPIRED');end if;case a
when 'heartbeat' then update app_private.backup_runs set lease_until=now()+interval '10 minutes' where id=p_id;
when 'snapshot' then update app_private.backup_runs set snapshot_at=(p_payload->>'snapshotAt')::timestamptz,data_epoch=(p_payload->>'dataEpoch')::uuid,migration_version=p_payload->>'migrationVersion' where id=p_id;
when 'complete' then if b.snapshot_at is null or b.data_epoch is distinct from(p_payload->>'dataEpoch')::uuid or b.migration_version is distinct from p_payload->>'migrationVersion' or b.snapshot_at is distinct from(p_payload->>'snapshotAt')::timestamptz then perform app_private.fail('VALIDATION_ERROR');end if;update app_private.backup_runs set status='succeeded',completed_at=now(),lease_token=null,lease_until=null,object_count=(p_payload->>'objectCount')::bigint,total_bytes=(p_payload->>'totalBytes')::bigint,manifest_sha256=p_payload->>'manifestSha256',archive_sha256=p_payload->>'archiveSha256' where id=p_id;
when 'fail' then if p_payload->>'errorCode' not in('LEASE_EXPIRED','HASH_MISMATCH','OBJECT_MISSING','DUMP_FAILED','ENCRYPTION_FAILED','OPERATOR_CANCELLED','DEPENDENCY_UNAVAILABLE') then perform app_private.fail('VALIDATION_ERROR');end if;update app_private.backup_runs set status='failed',completed_at=now(),lease_token=null,lease_until=null,error_code=p_payload->>'errorCode' where id=p_id;
else perform app_private.fail('VALIDATION_ERROR');end case;select * into b from app_private.backup_runs where id=p_id;return to_jsonb(b);end$$;

-- Function access is enumerated after all definitions, never inherited from PUBLIC.
do $$declare f record;begin for f in select p.oid::regprocedure signature,p.proname name from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and(p.proname like 'read_%' or p.proname like 'gateway_%') loop execute format('revoke all on function %s from public, anon, authenticated',f.signature);if f.name like 'read_%' then execute format('grant execute on function %s to anon, authenticated, service_role',f.signature);else execute format('grant execute on function %s to service_role',f.signature);end if;end loop;end$$;
revoke all on all tables in schema app_private from public,anon,authenticated;
revoke all on all functions in schema app_private from public,anon,authenticated;
insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types) values('photos','photos',false,524288,array['image/jpeg']) on conflict(id) do nothing;
